//go:build uatdiagnostics

package httpapi

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net"
	"net/url"
	"os"
	"path/filepath"
	"slices"
	"sync"
	"time"

	"wordweave/internal/ai"
)

const captureFilename = "failure.json"
const captureMaxBytes = 1 << 20

// A private ticket authorizes one precise reproduction, never all UAT traffic.
type captureTicket struct {
	ExpiresAt       time.Time `json:"expires_at"`
	ModelID         string    `json:"model_id"`
	MeaningLanguage string    `json:"meaning_language"`
	Scenario        string    `json:"scenario"`
	Length          string    `json:"length"`
	Entries         []string  `json:"entries"`
}

type uatFailureCapture struct {
	mu      sync.Mutex
	root    *os.Root
	ticket  captureTicket
	timer   *time.Timer
	claimed bool
	closed  bool
}

func newFailureCapture(origin string) (failureCapture, error) {
	directory := os.Getenv("UAT_FAILURE_CAPTURE_DIR")
	if directory == "" {
		return nil, nil
	}
	// Do not include paths, ticket contents, or wrapped filesystem errors in logs.
	invalid := errors.New("invalid private UAT failure capture configuration")
	parsed, err := url.Parse(origin)
	if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") {
		return nil, invalid
	}
	host := parsed.Hostname()
	if host != "localhost" && !net.ParseIP(host).IsLoopback() {
		return nil, invalid
	}
	if !filepath.IsAbs(directory) {
		return nil, invalid
	}
	info, err := os.Lstat(directory)
	if err != nil || !info.IsDir() || info.Mode().Perm() != 0o700 {
		return nil, invalid
	}
	root, err := os.OpenRoot(directory)
	if err != nil {
		return nil, invalid
	}
	accepted := false
	defer func() {
		if !accepted {
			_ = root.Close()
		}
	}()
	info, err = root.Lstat("ticket.json")
	if err != nil || !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 || info.Size() > 4096 {
		return nil, invalid
	}
	file, err := root.Open("ticket.json")
	if err != nil {
		return nil, invalid
	}
	raw, readErr := io.ReadAll(io.LimitReader(file, 4097))
	_ = file.Close()
	if readErr != nil || len(raw) > 4096 {
		return nil, invalid
	}
	var ticket captureTicket
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if decoder.Decode(&ticket) != nil || decoder.Decode(new(any)) != io.EOF {
		return nil, invalid
	}
	if ticket.ExpiresAt.IsZero() || ticket.ModelID == "" || len(ticket.Entries) == 0 || len(ticket.Entries) > 128 ||
		!slices.Contains([]string{"zh", "en", "ja"}, ticket.MeaningLanguage) ||
		!slices.Contains([]string{"story", "discussion", "business", "news"}, ticket.Scenario) ||
		!slices.Contains([]string{"short", "medium", "long", "xlong"}, ticket.Length) {
		return nil, invalid
	}
	remaining := time.Until(ticket.ExpiresAt)
	if remaining > time.Hour {
		return nil, invalid
	}
	capture := &uatFailureCapture{root: root, ticket: ticket}
	if info, err := root.Lstat(captureFilename); err == nil {
		// Restarting the same ticket must not overwrite or collect another sample.
		if !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 {
			return nil, invalid
		}
		capture.claimed = true
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, invalid
	}
	accepted = true
	if remaining <= 0 {
		capture.Close()
		return nil, nil
	}
	capture.mu.Lock()
	capture.timer = time.AfterFunc(remaining, capture.Close)
	capture.mu.Unlock()
	return capture, nil
}

func (capture *uatFailureCapture) Record(spec ai.GenerationSpec, candidate ai.Candidate, reason string, targetIndex int) {
	capture.mu.Lock()
	defer capture.mu.Unlock()
	if capture.closed || capture.claimed || !time.Now().Before(capture.ticket.ExpiresAt) ||
		spec.CompatibilityProbe || spec.ModelID != capture.ticket.ModelID ||
		spec.MeaningLanguage != capture.ticket.MeaningLanguage || spec.Scenario != capture.ticket.Scenario ||
		spec.LengthCode != capture.ticket.Length || !slices.Equal(spec.Entries, capture.ticket.Entries) {
		return
	}
	capture.claimed = true
	// Explicit allowlist: no request, actor, token, headers, credentials or error.Error().
	raw, err := json.MarshalIndent(struct {
		RunID            string       `json:"run_id"`
		CapturedAt       time.Time    `json:"captured_at"`
		ExpiresAt        time.Time    `json:"expires_at"`
		PromptVersion    string       `json:"prompt_version"`
		ValidatorVersion string       `json:"validator_version"`
		Reason           string       `json:"reason"`
		TargetIndex      int          `json:"target_index"`
		Candidate        ai.Candidate `json:"candidate"`
	}{spec.RunID, time.Now().UTC(), capture.ticket.ExpiresAt, spec.PromptVersion,
		ai.ValidatorVersion, reason, targetIndex, candidate}, "", "  ")
	if err != nil || len(raw) > captureMaxBytes {
		slog.Warn("uat_failure_capture_skipped", "reason", "sample_size_or_encoding")
		return
	}
	if !time.Now().Before(capture.ticket.ExpiresAt) {
		return
	}
	file, err := capture.root.OpenFile(captureFilename, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		slog.Warn("uat_failure_capture_skipped", "reason", "private_file_unavailable")
		return
	}
	_, writeErr := file.Write(raw)
	closeErr := file.Close()
	if writeErr != nil || closeErr != nil {
		_ = capture.root.Remove(captureFilename)
		slog.Warn("uat_failure_capture_skipped", "reason", "private_file_write_failed")
		return
	}
	slog.Info("uat_failure_candidate_captured", "run_id", spec.RunID)
}

func (capture *uatFailureCapture) Close() {
	capture.mu.Lock()
	defer capture.mu.Unlock()
	if capture.closed {
		return
	}
	capture.closed = true
	if capture.timer != nil {
		capture.timer.Stop()
	}
	if err := capture.root.Remove(captureFilename); err != nil && !errors.Is(err, os.ErrNotExist) {
		slog.Warn("uat_failure_capture_cleanup_failed")
	}
	_ = capture.root.Close()
}

